#include <iostream>
using std::cin;
using std::cout;
#include <vector>
using std::vector;

int main (void) {
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);

	int n, m;
	cin >> n >> m;

	vector<int> isused(m+1, 0);
	for (int i = 0; i < n; i++) {
		int len;
		cin >> len;

		vector<int> x(len);
		for (int j = 0; j < len; j++) {
			cin >> x[j];
		}

		int ans = 0;
		for (int j = 0; j < len; j++) {
			if (isused[x[j]] == 0) {
				isused[x[j]] = 1;
				ans = x[j];
				break;
			}
		}

		cout << ans << "\n";
	}

	return 0;
}
